CREATE TABLE IF NOT EXISTS shop_credit_account(company_id BIGINT PRIMARY KEY,credit_limit BIGINT NOT NULL DEFAULT 0,term_days INT NOT NULL DEFAULT 30,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_credit_order(order_id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,amount BIGINT NOT NULL,repaid BIGINT NOT NULL DEFAULT 0,refunded BIGINT NOT NULL DEFAULT 0,state VARCHAR(20) NOT NULL DEFAULT 'reserved',term_days INT NOT NULL,due_at DATETIME NULL,INDEX credit_company(company_id,state,due_at));
CREATE TABLE IF NOT EXISTS shop_credit_event(id BIGINT PRIMARY KEY AUTO_INCREMENT,company_id BIGINT NOT NULL,order_id BIGINT NULL,event_key VARCHAR(100) NOT NULL UNIQUE,kind VARCHAR(30) NOT NULL,amount BIGINT NOT NULL,note VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_credit_repayment(id BIGINT PRIMARY KEY AUTO_INCREMENT,company_id BIGINT NOT NULL,submitted_by BIGINT NOT NULL,submitted_account VARCHAR(40) NOT NULL,order_id BIGINT NOT NULL,amount BIGINT NOT NULL,proof VARCHAR(200) NOT NULL,payer VARCHAR(100) NOT NULL,request_key VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',confirmed_amount BIGINT NOT NULL DEFAULT 0,bank_reference VARCHAR(120) NULL UNIQUE,note VARCHAR(300) NULL,reviewer VARCHAR(64) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY repayment_request(submitted_by,request_key));
